css:
@page { size: A4 landscape; margin: 0; }
* { box-sizing: border-box; }
.certificate { position: relative; width: 100%; min-height: 720px; overflow: hidden; padding: 28px; color: #172033; font-family: Arial, Helvetica, sans-serif; background: #f7f3e8; }
.frame { position: relative; min-height: 664px; padding: 54px 74px 42px; text-align: center; border: 2px solid #123b63; background: #fffdf8; }
.frame:before { content: ''; position: absolute; inset: 10px; border: 1px solid #c5a45d; pointer-events: none; }
.corner { position: absolute; width: 92px; height: 92px; border-color: #c5a45d; border-style: solid; }
.corner.tl { top: 20px; left: 20px; border-width: 3px 0 0 3px; }
.corner.tr { top: 20px; right: 20px; border-width: 3px 3px 0 0; }
.corner.bl { bottom: 20px; left: 20px; border-width: 0 0 3px 3px; }
.corner.br { right: 20px; bottom: 20px; border-width: 0 3px 3px 0; }
.brand { min-height: 52px; margin-bottom: 28px; color: #123b63; font-size: 18px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.logo { display: inline-block; width: auto; max-width: 180px; height: 48px; margin: 0 12px -17px 0; object-fit: contain; }
.kicker { margin: 0 0 8px; color: #927334; font-size: 13px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; }
.title { margin: 0; color: #123b63; font-family: Georgia, 'Times New Roman', serif; font-size: 46px; font-weight: 400; letter-spacing: .04em; }
.rule { width: 92px; margin: 20px auto 22px; border-top: 2px solid #c5a45d; }
.lead { margin: 0 0 12px; color: #566276; font-size: 15px; }
.recipient { margin: 0 auto 13px; color: #172033; font-family: Georgia, 'Times New Roman', serif; font-size: 34px; font-weight: 700; line-height: 1.2; }
.copy { max-width: 720px; margin: 0 auto; color: #3f4b5c; font-size: 16px; line-height: 1.55; }
.course { color: #123b63; font-weight: 700; }
.meta { margin: 30px auto 0; width: 88%; table-layout: fixed; }
.meta td { width: 33.333%; padding: 0 18px; vertical-align: bottom; }
.meta-value { min-height: 28px; padding-bottom: 7px; color: #172033; font-size: 14px; font-weight: 700; border-bottom: 1px solid #8d98a7; }
.meta-label { padding-top: 7px; color: #727d8d; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.certificate-id { position: absolute; right: 32px; bottom: 27px; color: #87909d; font-size: 9px; letter-spacing: .08em; }
